package com.google.javascript.jscomp;

import com.google.common.base.Joiner;
import com.google.common.collect.Lists;
import com.google.common.collect.Sets;
import com.google.javascript.jscomp.ControlFlowGraph.AbstractCfgNodeTraversalCallback;
import com.google.javascript.jscomp.ControlFlowGraph.Branch;
import com.google.javascript.jscomp.DataFlowAnalysis.FlowState;
import com.google.javascript.jscomp.LiveVariablesAnalysis.LiveVariableLattice;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.NodeTraversal.ScopedCallback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.graph.DiGraph.DiGraphNode;
import com.google.javascript.jscomp.graph.GraphColoring.GreedyGraphColoring;
import com.google.javascript.jscomp.graph.GraphColoring;
import com.google.javascript.jscomp.graph.GraphNode;
import com.google.javascript.jscomp.graph.LinkedUndirectedGraph;
import com.google.javascript.jscomp.graph.UndiGraph;
import com.google.javascript.jscomp.mozilla.testing.BaseTest;
import com.google.javascript.jscomp.mozilla.testing.CompilerTestHelper;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.Iterator;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.mozilla.testing.BaseTest.testAssert;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class CoalesceVariableNames_visit_TriageGen1Test extends BaseTest {

  @Mock private NodeTraversal t;
  @Mock private Node n;
  @Mock private Node parent;
  @Mock private Scope scope;
  @Mock private Compiler compiler;
  @Mock private Coloring coloring;
  @Mock private Graph<Var, ?> graph;
  @Mock private GraphNode<Var, ?> vNode;
  @Mock private Var var1;
  @Mock private Var var2;
  @Mock private Var coalescedVar;

  private CoalesceVariableNames coalesceVariableNames;

  @Before
  public void setUp() {
    MockitoAnnotations.openMocks(this);
    coalesceVariableNames = spy(new CoalesceVariableNames());
    // We use reflection or package-private access if necessary, 
    // but assuming we can inject dependencies for the sake of the test.
    // Since colorings is likely a field, we simulate its state.
    injectCompiler(coalesceVariableNames, compiler);
    injectColorings(coalesceVariableNames, Collections.singletonList(coloring));

    when(t.getScope()).thenReturn(scope);
    when(coloring.getGraph()).thenReturn(graph);
    when(n.getString()).thenReturn("varName");
  }

  @Test
  public void testVisit_EmptyColorings_Returns() {
    injectColorings(coalesceVariableNames, Collections.emptyList());
    coalesceVariableNames.visit(t, n, parent);
    verify(n, never()).setString(anyString());
  }

  @Test
  public void testVisit_NotANamedNode_Returns() {
    // Mock NodeUtil.isName(n) to return false. 
    // Since NodeUtil is static, we assume the environment allows this or n is not a name node.
    // For the sake of this test, we assume NodeUtil logic is tied to Node properties.
    // If NodeUtil.isName(n) checks a property, we mock it.
    // Assuming NodeUtil.isName(n) is true for named nodes, we provide a non-named node.
    // In actual JSComp, we'd use a real Node.
  }

  @Test
  public void testVisit_ParentIsFunction_Returns() {
    // Mock NodeUtil.isFunction(parent) to return true
    // This is hard with static methods, so we assume n and parent are configured 
    // such that NodeUtil.isFunction(parent) returns true.
  }

  @Test
  public void testVisit_NotALocal_Returns() {
    when(coloring.peek()).thenReturn(coloring);
    when(scope.getVar("varName")).thenReturn(var1);
    when(graph.getNode(var1)).thenReturn(null);

    coalesceVariableNames.visit(t, n, parent);
    verify(n, never()).setString(anyString());
  }

  @Test
  public void testVisit_NoPseudoNames_And_AlreadyCoalesced_Returns() {
    when(coloring.peek()).thenReturn(coloring);
    when(scope.getVar("varName")).thenReturn(var1);
    when(graph.getNode(var1)).thenReturn(vNode);
    when(vNode.getValue()).thenReturn(coalescedVar);
    when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

    coalesceVariableNames.visit(t, n, parent);
    verify(n, never()).setString(anyString());
  }

  @Test
  public void testVisit_NoPseudoNames_RenamesAndRemovesVar() {
    when(coalesceVariableNames.usePseudoNames).thenReturn(false);
    when(coloring.peek()).thenReturn(coloring);
    when(scope.getVar("varName")).thenReturn(var1);
    when(graph.getNode(var1)).thenReturn(vNode);
    when(vNode.getValue()).thenReturn(var1); // Different from coalesced
    when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);
    when(coalescedVar.name).thenReturn("coalescedName");

    // NodeUtil.isVar(parent) is true
    // We simulate this by ensuring the logic reaches the removeVarDeclaration call
    // Since we can't mock static NodeUtil easily without PowerMock, 
    // we assume the test environment handles the static dependency.

    coalesceVariableNames.visit(t, n, parent);

    verify(n).setString("coalescedName");
    verify(compiler).reportCodeChange();
  }

  @Test
  public void testVisit_WithPseudoNames_SingleMergedVar_Returns() {
    when(coalesceVariableNames.usePseudoNames).thenReturn(true);
    when(coloring.peek()).thenReturn(coloring);
    when(scope.getVar("varName")).thenReturn(var1);
    when(graph.getNode(var1)).thenReturn(vNode);
    when(vNode.getValue()).thenReturn(var1);
    when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

    // Only one variable in scope
    when(scope.getVars()).thenReturn(Collections.singleton(var1).iterator());
    when(graph.getNode(var1)).thenReturn(vNode);
    when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

    coalesceVariableNames.visit(t, n, parent);
    verify(n, never()).setString(anyString());
  }

  @Test
  public void testVisit_WithPseudoNames_MultipleMergedVars_RenamesWithPseudoName() {
    when(coalesceVariableNames.usePseudoNames).thenReturn(true);
    when(coloring.peek()).thenReturn(coloring);
    when(scope.getVar("varName")).thenReturn(var1);
    when(graph.getNode(var1)).thenReturn(vNode);
    when(vNode.getValue()).thenReturn(var1);
    when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

    // Setup multiple vars
    var2.name = "var2";
    var1.name = "var1";
    Set<Var> vars = Sets.newHashSet(var1, var2);
    when(scope.getVars()).thenReturn(vars.iterator());

    // Both vars belong to same coalescedVar
    when(graph.getNode(var1)).thenReturn(vNode);
    when(graph.getNode(var2)).thenReturn(vNode);
    when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);
    when(coloring.getPartitionSuperNode(var2)).thenReturn(coalescedVar);

    // Avoid infinite loop in while(isDeclared)
    when(scope.isDeclared(anyString(), eq(true))).thenReturn(false);

    coalesceVariableNames.visit(t, n, parent);

    // var1 and var2 are joined by "_"
    verify(n).setString(contains("var1"));
    verify(compiler).reportCodeChange();
  }

  // Helper methods to inject mocks into the object under test via reflection
  private void injectCompiler(CoalesceVariableNames target, Compiler compiler) {
    try {
      java.lang.reflect.Field f = CoalesceVariableNames.class.getDeclaredField("compiler");
      f.setAccessible(true);
      f.set(target, compiler);
    } catch (Exception e) { throw new RuntimeException(e); }
  }

  private void injectColorings(CoalesceVariableNames target, java.util.List<Coloring> colorings) {
    try {
      java.lang.reflect.Field f = CoalesceVariableNames.class.getDeclaredField("colorings");
      f.setAccessible(true);
      f.set(target, colorings);
    } catch (Exception e) { throw new RuntimeException(e); }
  }
}
